def check(value, message):
    if not value:
        raise ValueError(message)


def verified_file(path, expected):
    path = Path(path).resolve(strict=True)
    check(expected and identity.sha(path) == expected, 'Changed identity file: ' + str(path))
    return path


def descriptor_inputs(descriptor):
    result = {}
    for key, value in descriptor.items():
        if key.endswith('File') and key + 'Sha256' in descriptor:
            result[key] = verified_file(value, descriptor[key + 'Sha256'])
    # Some existing descriptors use the shorter hash suffix for provenance/patch/source manifests.
    for field, digest in [('classpathManifestFile', 'classpathManifestSha256'),
                          ('sourceProvenanceFile', 'sourceProvenanceSha256'),
                          ('sourceManifestFile', 'sourceManifestSha256'),
                          ('originalSourceManifestFile', 'originalSourceManifestSha256'),
                          ('provenanceFile', 'provenanceSha256'),
                          ('productionPatchFile', 'productionPatchSha256')]:
        if field in descriptor:
            result[field] = verified_file(descriptor[field], descriptor[digest])
    return result


